e->false transition is already observed\n -- by the source trigger; repeated explicit stop still advances the monotonic marker.\n if was_enabled is false then\n  update ops_control_private.budget_fences_v1 f set revision=revision+1,stop_revision=revision+1\n   where scope_id=sid and(owner_id=uid or retired and owner_id is null)\n   and exists(select 1 from public.model_budget_scopes s where s.id=sid and s.owner_id=uid\n    and s.created_at=f.scope_created_at and not s.enabled);\n  -- A generation already retired remains closed even if there is no further\n  -- writable marker. Do not make original stopping/settlement fail to open it.\n end if;\nend $function$\n","volatility":"v","securityDefiner":true},"ops_control_private.revision_v1(jsonb)":{"acl":"{postgres=X/postgres}","md5":"950b31476f8506ec54d54288b94dad35","kind":"f","owner":"postgres","config":["search_path=\"\""],"prosrc":"\nbegin\n if jsonb_typeof(v) is distinct from ''number'' or v::text !~ ''^(0|[1-9][0-9]*)$'' then return false;end if;\n return(v::text)::numeric between 0 and 9007199254740990;\nend\n","result":"boolean","strict":false,"identity":"v jsonb","language":"plpgsql","parallel":"u","arguments":"v jsonb","signature":"ops_control_private.revision_v1(jsonb)","definition":"CREATE OR REPLACE FUNCTION ops_control_private.revision_v1(v jsonb)\n RETURNS boolean\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''''\nAS $function$\nbegin\n if jsonb_typeof(v) is distinct from ''number'' or v::text !~ ''^(0|[1-9][0-9]*)$'' then return false;end if;\n return(v::text)::numeric between 0 and 9007199254740990;\nend\n$function$\n","volatility":"i","securityDefiner":false},"ops_control_private.stamp_v1(timestamp with time zone)":{"acl":"{postgres=X/postgres}","md5":"1a2495ed58b4582a87879ca6e2f0fdbf","kind":"f","owner":"postgres","config":["search_path=\"\""],"prosrc":"\n select to_char(v at time zone ''UTC'',''YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'')\n","result":"text","strict":false,"identity":"v timestamp with time zone","language":"sql","parallel":"u","arguments":"v timestamp with time zone","signature":"ops_control_private.stamp_v1(timestamp with time zone)","definition":"CREATE OR REPLACE FUNCTION ops_control_private.stamp_v1(v timestamp with time zone)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''''\nAS $function$\n select to_char(v at time zone ''UTC'',''YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'')\n$function$\n","volatility":"i","securityDefiner":false},"ops_control_private.uuid_v1(jsonb)":{"acl":"{postgres=X/postgres}","md5":"39d64d3b17ca47d0cf4e74f0368b0058","kind":"f","owner":"postgres","config":["search_path=\"\""],"prosrc":"\n select coalesce(jsonb_typeof(v)=''string'' and v#>>''{}'' ~ ''^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'',false)\n","result":"boolean","strict":false,"identity":"v jsonb","language":"sql","parallel":"u","arguments":"v jsonb","signature":"ops_control_private.uuid_v1(jsonb)","definition":"CREATE OR REPLACE FUNCTION ops_control_private.uuid_v1(v jsonb)\n RETURNS boolean\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''''\nAS $function$\n select coalesce(jsonb_typeof(v)=''string'' and v#>>''{}'' ~ ''^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'',false)\n$function$\n","volatility":"i","securityDefiner":false},"ops_control_private.work_allowed_v1(uuid,uuid,text)":{"acl":"{postgres=X/postgres}","md5":"cef139b2aeeef0d6b19b6a712c655053","kind":"f","owner":"postgres","config":["search_path=\"\""],"prosrc":"\n select ops_control_private.work_decision_v1(turn_n,lease_n,effect_n)->>''kind''=''allowed''\n","result":"boolean","strict":false,"identity":"turn_n uuid, lease_n uuid, effect_n text","language":"sql","parallel":"u","arguments":"turn_n uuid, lease_n uuid, effect_n text","signature":"ops_control_private.work_allowed_v1(uuid,uuid,text)","definition":"CREATE OR REPLACE FUNCTION ops_control_private.work_allowed_v1(turn_n uuid, lease_n uuid, effect_n text)\n RETURNS boolean\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\n select ops_control_private.work_decision_v1(turn_n,lease_n,effect_n)->>''kind''=''allowed''\n$function$\n","volatility":"v","securityDefiner":true},"ops_control_private.work_basis_v1(uuid,uuid,text)":{"acl":"{postgres=X/postgres}","md5":"1ed7c00cb658d4c832d0d9e8a0955ad4","kind":"f","owner":"postgres","config":["search_path=\"\""],"prosrc":"\ndeclare w turn_private.work%rowtype;c turn_private.text_content%rowtype;\n p turn_private.text_policies%rowtype;g turn_private.grounded_turns%rowtype;\n run_n turn_private.planning_v2_execution_runs%rowtype;\n profile_n turn_private.planning_v2_execution_profiles%rowtype;\n tariff_n turn_private.planning_v2_registered_tariffs%rowtype;\n scoped_n scoped_edit_private.work_v1%rowtype;cfg_n scoped_edit_private.worker_settings_v1%rowtype;\n q jsonb;city_n text;provider_n text;\n task_n turn_private.service_tasks%rowtype;\nbegin\n -- Original entry already holds the authorizing source locks. Late reads use NOWAIT;\n -- there is no global-control lock followed by a new owner/task/policy lock.\n if effect_n not in(''admission'',''model'',''tool'') or effect_n is null then return null;end if;\n select * into w from turn_private.work where turn_id=turn_n for share nowait;\n if not found then return null;end if;\n if not exists(select 1 from public.turns where id=w.turn_id and owner_id=w.owner_id\n  and status not in(''completed'',''proposal_ready'',''unavailable'',''failed'',''cancelled'')) then return null;end if;\n if effect_n=''admission'' then\n  if w.state<>''queued'' then return null;end if;\n else\n  if w.state<>''leased'' or w.lease_token is distinct from lease_n\n   or w.expires_at<=clock_timestamp() then return null;end if;\n end if;\n select * into c from turn_private.text_content where turn_id=w.turn_id and owner_id=w.owner_id\n  and hidden_at is null for share nowait;\n if not found then return null;end if;\n select * into p from turn_private.text_policies where id=c.policy_id for share nowait;\n if not found or not turn_private.text_policy_current(p.id)\n  or not exists(select 1 from turn_private.text_consents where owner_id=w.owner_id and policy_id=c.policy_id\n   and consent_id=c.consent_id and revoked_at is null)\n  or not exists(select 1 from auth.sessions where id=w.session_id and user_id=w.owner_id)\n  then return null;end if;\n provider_n:=p.provider;\n if w.execution_mode=''planning_intake_comparison_v2'' then\n  q:=turn_private.read_planning_qualified_intake_v1(w.owner_id,w.turn_id,\n   case when effect_n=''admission'' then null else lease_n end);\n  if q->>''kind'' is distinct from ''planning_intake_input'' then return null;end if;\n  city_n:=q->''qualifiedIntake''->''intake''->>''city'';\n  if city_n is distinct from ''shanghai'' then return null;end if;\n  if effect_n<>''admission'' then\n   select * into run_n from turn_private.planning_v2_execution_runs where turn_id=w.turn_id and owner_id=w.owner_id;\n   if not found or run_n.task_id::text is distinct from q->>''taskId'' then return null;end if;\n   select * into profile_n from turn_private.planning_v2_execution_profiles where id=run_n.profile_id for share nowait;\n   if not found or profile_n.owner_id<>w.owner_id or profile_n.revision<>run_n.profile_revision\n    or to_jsonb(profile_n) is distinct from run_n.profile_snapshot or profile_n.text_policy_id<>p.id\n    or profile_n.planning_policy_id::text is distinct from q->>''planningPolicyId'' then return null;end if;\n   select * into tariff_n from turn_private.planning_v2_registered_tariffs where id=profile_n.tariff_id for share nowait;\n   if not found or run_n.execution->>''provider'' is distinct from tariff_n.provider\n    or run_n.execution->>''model'' is distinct from tariff_n.model\n    or run_n.execution->>''priceVersion'' is distinct from tariff_n.price_version then return null;end if;\n   provider_n:=tariff_n.provider;\n  end if;\n elsif w.execution_mode=''text'' then\n  select * into g from turn_private.grounded_turns where turn_id=w.turn_id and owner_id=w.owner_id for share nowait;\n  if found then\n   if not exists(select 1 from turn_private.service_task_turns st where st.turn_id=w.turn_id\n    and st.owner_id=w.owner_id and st.task_id=g.task_id)\n    then return null;end if;\n   city_n:=g.city;\n  end if;\n elsif w.execution_mode=''scoped_trip_edit_v1'' then\n  select * into scoped_n from scoped_edit_private.work_v1 where turn_id=w.turn_id and owner_id=w.owner_id for share nowait;\n  if not found or scoped_n.policy_id<>p.id\n   or not exists(select 1 from turn_private.service_task_turns st where st.turn_id=w.turn_id\n    and st.owner_id=w.owner_id and st.task_id=scoped_n.task_id) then return null;end if;\n  select * into cfg_n from scoped_edit_private.worker_settings_v1 where policy_id=scoped_n.policy_id for share nowait;\n  if not found or not cfg_n.enabled or cfg_n.expires_at<=clock_timestamp()\n   or cfg_n.scope_id<>scoped_n.scope_id or p.provider is distinct from ''qwen''\n   or not scoped_edit_private.worker_policy_v1(w.owner_id,scoped_n.policy_id,scoped_n.scope_id) then return null;end if;\n  if effect_n=''admission'' then provider_n:=''qwen'';\n  else\n   if scoped_n.binding->>''provider'' is distinct from ''qwen''\n    or scoped_n.binding->>''model'' is distinct from cfg_n.model\n    or scoped_n.binding->>''priceVersion'' is distinct from cfg_n.price_version then return null;end if;\n   provider_n:=scoped_n.binding->>''provider'';\n  end if;\n elsif w.execution_mode<>''planning_comparison_v1'' then return null;\n end if;\n if effect_n=''tool'' then\n  if w.execution_mode not in(''planning_comparison_v1'',''planning_intake_comparison_v2'') then return null;end if;\n  provider_n:=''amap'';\n end if;\n select t.* into task_n from turn_private.service_tasks t join turn_private.service_task_turns st\n  on st.task_id=t.id and st.owner_id=t.owner_id where st.turn_id=w.turn_id and t.owner_id=w.owner_id for share of t nowait;\n if task_n.id is not null then\n  if task_n.policy_id<>c.policy_id or task_n.consent_id<>c.consent_id or task_n.thread_id<>c.thread_id\n   or not exists(select 1 from turn_private.text_content goal where goal.turn_id=task_n.goal_turn_id\n    and goal.owner_id=w.owner_id and goal.hidden_at is null) then return null;end if;\n  if p.context_mode=''task_history_v1'' and turn_private.task_history(w.turn_id) is null then return null;end if;\n  if g.turn_id is not null and g.scope_version<>task_n.scope_version then return null;end if;\n elsif w.execution_mode<>''text'' or p.context_mode<>''current_input_v1''\n  or exists(select 1 from turn_private.service_task_turns where turn_id=w.turn_id)\n  or exists(select 1 from turn_private.service_tasks where id=w.turn_id) then return null;\n end if;\n -- This internal proof is not exposed as an actor/lease/source DTO.\n return jsonb_build_object(''mode'',w.execution_mode,''provider'',provider_n,''city'',city_n,''taskId'',coalesce(task_n.id,w.turn_id),\n  ''canonicalTask'',task_n.id is not null,\n  ''scopeId'',task_n.budget_scope_id,''model'',case\n   when w.execution_mode=''planning_intake_comparison_v2'' and effect_n<>''admission'' then tariff_n.model\n   when w.execution_mode=''scoped_trip_edit_v1'' then cfg_n.model\n   when provider_n=''qwen'' then ''qwen3.7-plus-2026-05-26'' when provider_n=''glm'' then ''glm-5.3-flash''\n   when provider_n=''deepseek'' then ''deepseek-flash'' else null end,\n  ''priceVersion'',case when w.execution_mode=''planning_intake_comparison_v2'' and effect_n<>''admission'' then tariff_n.price_version\n   when w.execution_mode=''scoped_trip_edit_v1'' then cfg_n.price_version else null end);\nexception when lock_not_available then return null;\nend ","result":"jsonb","strict":false,"identity":"turn_n uuid, lease_n uuid, effect_n text","language":"plpgsql","parallel":"u","arguments":"turn_n uuid, lease_n uuid, effect_n text","signature":"ops_control_private.work_basis_v1(uuid,uuid,text)","definition":"CREATE OR REPLACE FUNCTION ops_control_private.work_basis_v1(turn_n uuid, lease_n uuid, effect_n text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare w turn_private.work%rowtype;c turn_private.text_content%rowtype;\n p turn_private.text_policies%rowtype;g turn_private.grounded_turns%rowtype;\n run_n turn_private.planning_v2_execution_runs%rowtype;\n profile_n turn_private.planning_v2_execution_profiles%rowtype;\n tariff_n turn_private.planning_v2_registered_tariffs%rowtype;\n scoped_n scoped_edit_private.work_v1%rowtype;cfg_n scoped_edit_private.worker_settings_v1%rowtype;\n q jsonb;city_n text;provider_n text;\n task_n turn_private.service_tasks%rowtype;\nbegin\n -- Original entry already holds the authorizing source locks. Late reads use NOWAIT;\n -- there is no global-control lock followed by a new owner/task/policy lock.\n if effect_n not in(''admission'',''model'',''tool'') or effect_n is null then return null;end if;\n select * into w from turn_private.work where turn_id=turn_n for share nowait;\n if not found then return null;end if;\n if not exists(select 1 from public.turns where id=w.turn_id and owner_id=w.owner_id\n  and status not in(''completed'',''proposal_ready'',''unavailable'',''failed'',''cancelled'')) then return null;end if;\n if effect_n=''admission'' then\n  if w.state<>''queued'' then return null;end if;\n else\n  if w.state<>''leased'' or w.lease_token is distinct from lease_n\n   or w.expires_at<=clock_timestamp() then return null;end if;\n end if;\n select * into c from turn_private.text_content where turn_id=w.turn_id and owner_id=w.owner_id\n  and hidden_at is null for share nowait;\n if not found then return null;end if;\n select * into p from turn_private.text_policies where id=c.policy_id for share nowait;\n if not found or not turn_private.text_policy_current(p.id)\n  or not exists(select 1 from turn_private.text_consents where owner_id=w.owner_id and policy_id=c.policy_id\n   and consent_id=c.consent_id and revoked_at is null)\n  or not exists(select 1 from auth.sessions where id=w.session_id and user_id=w.owner_id)\n  then return null;end if;\n provider_n:=p.provider;\n if w.execution_mode=''planning_intake_comparison_v2'' then\n  q:=turn_private.read_planning_qualified_intake_v1(w.owner_id,w.turn_id,\n   case when effect_n=''admission'' then null else lease_n end);\n  if q->>''kind'' is distinct from ''planning_intake_input'' then return null;end if;\n  city_n:=q->''qualifiedIntake''->''intake''->>''city'';\n  if city_n is distinct from ''shanghai'' then return null;end if;\n  if effect_n<>''admission'' then\n   select * into run_n from turn_private.planning_v2_execution_runs where turn_id=w.turn_id and owner_id=w.owner_id;\n   if not found or run_n.task_id::text is distinct from q->>''taskId'' then return null;end if;\n   select * into profile_n from turn_private.planning_v2_execution_profiles where id=run_n.profile_id for share nowait;\n   if not found or profile_n.owner_id<>w.owner_id or profile_n.revision<>run_n.profile_revision\n    or to_jsonb(profile_n) is distinct from run_n.profile_snapshot or profile_n.text_policy_id<>p.id\n    or profile_n.planning_policy_id::text is distinct from q->>''planningPolicyId'' then return null;end if;\n   select * into tariff_n from turn_private.planning_v2_registered_tariffs where id=profile_n.tariff_id for share nowait;\n   if not found or run_n.execution->>''provider'' is distinct from tariff_n.provider\n    or run_n.execution->>''model'' is distinct from tariff_n.model\n    or run_n.execution->>''priceVersion'' is distinct from tariff_n.price_version then return null;end if;\n   provider_n:=tariff_n.provider;\n  end if;\n elsif w.execution_mode=''text'' then\n  select * into g from turn_private.grounded_turns where turn_id=w.turn_id and owner_id=w.owner_id for share nowait;\n  if found then\n   if not exists(select 1 from turn_private.service_task_turns st where st.turn_id=w.turn_id\n    and st.owner_id=w.owner_id and st.task_id=g.task_id)\n    then return null;end if;\n   city_n:=g.city;\n  end if;\n elsif w.execution_mode=''scoped_trip_edit_v1'' then\n  select * into scoped_n from scoped_edit_private.work_v1 where turn_id=w.turn_id and owner_id=w.owner_id for share nowait;\n  if not found or scoped_n.policy_id<>p.id\n   or not exists(select 1 from turn_private.service_task_turns st where st.turn_id=w.turn_id\n    and st.owner_id=w.owner_id and st.task_id=scoped_n.task_id) then return null;end if;\n  select * into cfg_n from scoped_edit_private.worker_settings_v1 where policy_id=scoped_n.policy_id for share nowait;\n  if not found or not cfg_n.enabled or cfg_n.expires_at<=clock_timestamp()\n   or cfg_n.scope_id<>scoped_n.scope_id or p.provider is distinct from ''qwen''\n   or not scoped_edit_private.worker_policy_v1(w.owner_id,scoped_n.policy_id,scoped_n.scope_id) then return null;end if;\n  if effect_n=''admission'' then provider_n:=''qwen'';\n  else\n   if scoped_n.binding->>''provider'' is distinct from ''qwen''\n    or scoped_n.binding->>''model'' is distinct from cfg_n.model\n    or scoped_n.binding->>''priceVersion'' is distinct from cfg_n.price_version then return null;end if;\n   provider_n:=scoped_n.binding->>''provider'';\n  end if;\n elsif w.execution_mode<>''planning_comparison_v1'' then return null;\n end if;\n if effect_n=''tool'' then\n  if w.execution_mode not in(''planning_comparison_v1'',''planning_intake_comparison_v2'') then return null;end if;\n  provider_n:=''amap'';\n end if;\n select t.* into task_n from turn_private.service_tasks t join turn_private.service_task_turns st\n  on st.task_id=t.id and st.owner_id=t.owner_id where st.turn_id=w.turn_id and t.owner_id=w.owner_id for share of t nowait;\n if task_n.id is not null then\n  if task_n.policy_id<>c.policy_id or task_n.consent_id<>c.consent_id or task_n.thread_id<>c.thread_id\n   or not exists(select 1 from turn_private.text_content goal where goal.turn_id=task_n.goal_turn_id\n    and goal.owner_id=w.owner_id and goal.hidden_at is null) then return null;end if;\n  if p.context_mode=''task_history_v1'' and turn_private.task_history(w.turn_id) is null then return null;end if;\n  if g.turn_id is not null and g.scope_version<>task_n.scope_version then return null;end if;\n elsif w.execution_mode<>''text'' or p.context_mode<>''current_input_v1''\n  or exists(select 1 from turn_private.service_task_turns where turn_id=w.turn_id)\n  or exists(select 1 from turn_private.service_tasks where id=w.turn_id) then return null;\n end if;\n -- This internal proof is not exposed as an actor/lease/source DTO.\n return jsonb_build_object(''mode'',w.execution_mode,''provider'',provider_n,''city'',city_n,''taskId'',coalesce(task_n.id,w.turn_id),\n  ''canonicalTask'',task_n.id is not null,\n  ''scopeId'',task_n.budget_scope_id,''model'',case\n   when w.execution_mode=''planning_intake_comparison_v2'' and effect_n<>''admission'' then tariff_n.model\n   when w.execution_mode=''scoped_trip_edit_v1'' then cfg_n.model\n   when provider_n=''qwen'' then ''qwen3.7-plus-2026-05-26'' when provider_n=''glm'' then ''glm-5.3-flash''\n   when provider_n=''deepseek'' then ''deepseek-flash'' else null end,\n  ''priceVersion'',case when w.execution_mode=''planning_intake_comparison_v2'' and effect_n<>''admission'' then tariff_n.price_version\n   when w.execution_mode=''scoped_trip_edit_v1'' then cfg_n.price_version else null end);\nexception when lock_not_available then return null;\nend $function$\n","volatility":"v","securityDefiner":true},"ops_control_private.work_decision_v1(uuid,uuid,text)":{"acl":"{postgres=X/postgres}","md5":"5a0c44f075c0cc065b3a9fbf6f57f6fd","kind":"f","owner":"postgres","config":["search_path=\"\""],"prosrc":"\ndeclare b jsonb;\nbegin\n b:=ops_control_private.work_basis_v1(turn_n,lease_n,effect_n);\n -- A policy/source/lease denial never becomes an Ops refusal or an Ops side channel.\n if b is null then return jsonb_build_object(''kind'',''blocked'');end if;\n return ops_control_private.control_decision_v1(b->>''mode'',b->>''provider'',b->>''city'');\nend ","result":"jsonb","strict":false,"identity":"turn_n uuid, lease_n uuid, effect_n text","language":"plpgsql","parallel":"u","arguments":"turn_n uuid, lease_n uuid, effect_n text","signature":"ops_control_private.work_decision_v1(uuid,uuid,text)","definition":"CREATE OR REPLACE FUNCTION ops_control_private.work_decision_v1(turn_n uuid, lease_n uuid, effect_n text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare b jsonb;\nbegin\n b:=ops_control_private.work_basis_v1(turn_n,lease_n,effect_n);\n -- A policy/source/lease denial never becomes an Ops refusal or an Ops side channel.\n if b is null then return jsonb_build_object(''kind'',''blocked'');end if;\n return ops_control_private.control_decision_v1(b->>''mode'',b->>''provider'',b->>''city'');\nend $function$\n","volatility":"v","securityDefiner":true},"profile_data_private.schema_v1()":{"acl":"{postgres=X/postgres}","md5":"13fb1dfda51b271b1bcda539be2a3c7f","kind":"f","owner":"postgres","config":["search_path=\"\""],"prosrc":"\ndeclare r record;actual jsonb;expected jsonb;fk jsonb;names text[]:=array[''public.user_profiles'',''turn_private.assistant_directions_intakes_v1'',''turn_private.directions_operations_v1'',''turn_private.directions_result_sources_v1''];begin\n if not turn_private.directions_schema_members_v1() then return false;end if;\n -- Exact approved full application delta; unknown unlinked application tables\n -- also fail closed. Managed namespace checks remain the original fixed helper.\n if not result_data_private.infrastructure_supported_v1() or profile_data_private.digest_v1((select coalesce(jsonb_agg(jsonb_build_object(''relation'',n.nspname||''.''||c.relname,''columns'',(select jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull) order by a.attnum) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),''constraints'',(select jsonb_agg(pg_get_constraintdef(k.oid) order by k.conname) from pg_constraint k where k.conrelid=c.oid)) order by n.nspname,c.relname),''[]''::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind=''r'' and n.nspname not in(''pg_catalog'',''information_schema'',''extensions'',''auth'',''result_data_private'',''storage'',''realtime'',''_realtime'',''vault'',''supabase_functions'',''supabase_migrations''))::text)<> ''c35b58a5b5744c5ea02ccc818435d060a3da5078fe6353c6d5c1b9d0f5c5f161'' then return false;end if;\n for r in select * from profile_data_private.sources_v1() loop names:=names||r.relation_name;end loop;\n expected:=''{\"public.turns\":{\"columns\":[[\"id\",\"uuid\",true],[\"owner_id\",\"uuid\",true],[\"trip_id\",\"uuid\",false],[\"status\",\"text\",true],[\"created_at\",\"timestamp with time zone\",true],[\"thread_id\",\"uuid\",false],[\"updated_at\",\"timestamp with time zone\",true]],\"constraints\":[\"UNIQUE (id, owner_id)\",\"FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE\",\"PRIMARY KEY (id)\",\"CHECK ((status = ANY (ARRAY[''''accepted''''::text, ''''planning''''::text, ''''retrieving''''::text, ''''generating''''::text, ''''validating''''::text, ''''completed''''::text, ''''proposal_ready''''::text, ''''unavailable''''::text, ''''failed''''::text, ''''cancelled''''::text])))\",\"FOREIGN KEY (thread_id) REFERENCES public.chat_threads(id) ON DELETE CASCADE\",\"FOREIGN KEY (trip_id) REFERENCES public.trips(id) ON DELETE SET NULL\"]},\"turn_private.work\":{\"columns\":[[\"turn_id\",\"uuid\",true],[\"owner_id\",\"uuid\",true],[\"session_id\",\"uuid\",true],[\"state\",\"text\",true],[\"attempt\",\"integer\",true],[\"max_attempts\",\"integer\",true],[\"lease_ms\",\"integer\",true],[\"lease_token\",\"uuid\",false],[\"expires_at\",\"timestamp with time zone\",false],[\"created_at\",\"timestamp with time zone\",true],[\"execution_mode\",\"text\",true]],\"constraints\":[\"TRIGGER DEFERRABLE INITIALLY DEFERRED\",\"CHECK (((attempt >= 0) AND (attempt <= 5)))\",\"CHECK (((state = ''''leased''''::text) = ((lease_token IS NOT NULL) AND (expires_at IS NOT NULL))))\",\"CHECK (((state = ''''leased''''::text) OR ((lease_token IS NULL) AND (expires_at IS NULL))))\",\"CHECK ((execution_mode = ANY (ARRAY[''''text''''::text, ''''planning_comparison_v1''''::text, ''''planning_intake_comparison_v2''''::text, ''''scoped_trip_edit_v1''''::text, ''''travel_directions_v1''''::text])))\",\"CHECK (((lease_ms >= 1000) AND (lease_ms <= 300000)))\",\"CHECK (((max_attempts >= 1) AND (max_attempts <= 5)))\",\"FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE\",\"PRIMARY KEY (turn_id)\",\"CHECK ((state = ANY (ARRAY[''''queued''''::text, ''''leased''''::text, ''''completed''''::text, ''''failed''''::text, ''''cancelled''''::text, ''''quarantined''''::text])))\",\"FOREIGN KEY (turn_id) REFERENCES public.turns(id) ON DELETE CASCADE\"]},\"public.user_profiles\":{\"columns\":[[\"owner_id\",\"uuid\",true],[\"display_name\",\"text\",false],[\"travel_pace\",\"text\",true],[\"locale\",\"text\",true],[\"currency\",\"text\",true],[\"distance_unit\",\"text\",true],[\"temperature_unit\",\"text\",true],[\"default_departure_time\",\"time without time zone\",true],[\"created_at\",\"timestamp with time zone\",true],[\"updated_at\",\"timestamp with time zone\",true],[\"pace_revision\",\"bigint\",true],[\"pace_state\",\"text\",true],[\"pace_notice\",\"text\",false],[\"pace_operation\",\"uuid\",false],[\"pace_request\",\"jsonb\",false],[\"pace_undo\",\"jsonb\",false],[\"profile_revision\",\"bigint\",true],[\"profile_saved_fields\",\"jsonb\",true]],\"constraints\":[\"CHECK (((pace_state <> ALL (ARRAY[''''explicit''''::text, ''''paused''''::text])) OR (pace_notice IS NOT NULL)))\",\"CHECK ((currency = ANY (ARRAY[''''CNY''''::text, ''''USD''''::text, ''''EUR''''::text, ''''RUB''''::text, ''''SAR''''::text])))\",\"CHECK (((display_name IS NULL) OR ((char_length(display_name) >= 1) AN