ating''''::text, ''''validating''''::text, ''''completed''''::text, ''''proposal_ready''''::text, ''''unavailable''''::text, ''''failed''''::text, ''''cancelled''''::text])))\",\"FOREIGN KEY (thread_id) REFERENCES public.chat_threads(id) ON DELETE CASCADE\",\"FOREIGN KEY (trip_id) REFERENCES public.trips(id) ON DELETE SET NULL\"]},\"turn_private.work\":{\"columns\":[[\"turn_id\",\"uuid\",true],[\"owner_id\",\"uuid\",true],[\"session_id\",\"uuid\",true],[\"state\",\"text\",true],[\"attempt\",\"integer\",true],[\"max_attempts\",\"integer\",true],[\"lease_ms\",\"integer\",true],[\"lease_token\",\"uuid\",false],[\"expires_at\",\"timestamp with time zone\",false],[\"created_at\",\"timestamp with time zone\",true],[\"execution_mode\",\"text\",true]],\"constraints\":[\"TRIGGER DEFERRABLE INITIALLY DEFERRED\",\"CHECK (((attempt >= 0) AND (attempt <= 5)))\",\"CHECK (((state = ''''leased''''::text) = ((lease_token IS NOT NULL) AND (expires_at IS NOT NULL))))\",\"CHECK (((state = ''''leased''''::text) OR ((lease_token IS NULL) AND (expires_at IS NULL))))\",\"CHECK ((execution_mode = ANY (ARRAY[''''text''''::text, ''''planning_comparison_v1''''::text, ''''planning_intake_comparison_v2''''::text, ''''scoped_trip_edit_v1''''::text, ''''travel_directions_v1''''::text])))\",\"CHECK (((lease_ms >= 1000) AND (lease_ms <= 300000)))\",\"CHECK (((max_attempts >= 1) AND (max_attempts <= 5)))\",\"FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE\",\"PRIMARY KEY (turn_id)\",\"CHECK ((state = ANY (ARRAY[''''queued''''::text, ''''leased''''::text, ''''completed''''::text, ''''failed''''::text, ''''cancelled''''::text, ''''quarantined''''::text])))\",\"FOREIGN KEY (turn_id) REFERENCES public.turns(id) ON DELETE CASCADE\"]},\"public.user_profiles\":{\"columns\":[[\"owner_id\",\"uuid\",true],[\"display_name\",\"text\",false],[\"travel_pace\",\"text\",true],[\"locale\",\"text\",true],[\"currency\",\"text\",true],[\"distance_unit\",\"text\",true],[\"temperature_unit\",\"text\",tr