oken,p_turn_id,c.consent_id,c.policy_id) on conflict do nothing;\n if not found then return jsonb_build_object(''kind'',''blocked''); end if;\n return jsonb_build_object(''kind'',''authorized'');\nend ","result":"jsonb","strict":false,"identity":"p_turn_id uuid, p_lease_token uuid, p_policy_id uuid, p_provider text, p_context_digest text","language":"plpgsql","parallel":"u","arguments":"p_turn_id uuid, p_lease_token uuid, p_policy_id uuid, p_provider text, p_context_digest text","signature":"public.authorize_grounded_dispatch(uuid,uuid,uuid,text,text)","definition":"CREATE OR REPLACE FUNCTION public.authorize_grounded_dispatch(p_turn_id uuid, p_lease_token uuid, p_policy_id uuid, p_provider text, p_context_digest text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare ops_decision jsonb; payload jsonb; c turn_private.text_content%rowtype;\nbegin\n if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) and guide_private.bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object(''kind'',''blocked'');end if;\n  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in(''planning_intake_comparison_v2'',''scoped_trip_edit_v1'',''travel_directions_v1'')) then return jsonb_build_object(''kind'',''blocked''); end if;\n payload:=public.read_grounded_work(p_turn_id,p_lease_token);\n if payload->>''kind'' is distinct from ''intent_input'' or payload->>''policyId'' is distinct from p_policy_id::text\n   or payload->>''provider'' is distinct from p_provider or payload->>''contextDigest'' is distinct from p_context_digest then return jsonb_build_object(''kind'',''blocked''); end if;\n select * into c from turn_private.text_content where turn_id=p_turn_id;\n ops_decision:=ops_control_private.work_decision_v1(p_turn_id,p_lease_token,''model'');if ops_decision->>''kind'' is distinct from ''allowed'' then if ops_decision ? ''code'' then return ops_decision;end if;return jsonb_build_object(''kind'',''blocked'');end if;\ninsert into turn_private.text_dispatches(lease_token,turn_id,consent_id,policy_id) values(p_lease_token,p_turn_id,c.consent_id,c.policy_id) on conflict do nothing;\n if not found then return jsonb_build_object(''kind'',''blocked''); end if;\n return jsonb_build_object(''kind'',''authorized'');\nend $function$\n","volatility":"v","securityDefiner":true},"public.authorize_planning_dispatch_v1(uuid,uuid,text,uuid,uuid)":{"acl":"{postgres=X/postgres,service_role=X/postgres}","md5":"dc2e700aea6ebbe6682b3bea6baf1120","kind":"f","owner":"postgres","config":["search_path=\"\""],"prosrc":"\ndeclare ops_decision jsonb; payload jsonb; w turn_private.work%rowtype; c turn_private.text_content%rowtype; j turn_private.planning_comparisons%rowtype;\nbegin\n  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in(''planning_intake_comparison_v2'',''scoped_trip_edit_v1'',''travel_directions_v1'')) then return jsonb_build_object(''kind'',''blocked''); end if;\n  if (select auth.role())<>''service_role'' or p_context_digest !~ ''^[a-f0-9]{64}$''\n    or p_scope_id is null or p_attempt_id is null then raise exception ''INVALID_INPUT''; end if;\n  payload:=public.read_planning_comparison_work_v1(p_turn_id,p_lease_token);\n  if payload->>''kind''<>''planning_input'' or payload->>''contextDigest'' is distinct from p_context_digest then return jsonb_build_object(''kind'',''blocked''); end if;\n  select * into w from turn_private.work where turn_id=p_turn_id;\n  select * into j from turn_private.planning_comparisons where turn_id=p_turn_id;\n  select * into c from turn_private.text_content where turn_id=p_turn_id;\n  if not exists(select 1 from public.model_budget_attempts a join public.model_budget_scopes s on s.id=a.scope_id\n    where a.scope_id=p_scope_id and a.attempt_id=p_attempt_id and a.task_id=j.task_id and a.status=''dispatched''\n      and s.owner_id=w.owner_id and a.provider=payload->>''provider'' and s.enabled and not s.frozen and s.expires_at>clock_timestamp())\n    then return jsonb_build_object(''kind'',''blocked''); end if;\n  ops_decision:=ops_control_private.work_decision_v1(p_turn_id,p_lease_token,''model'');if ops_decision->>''kind'' is distinct from ''allowed'' then if ops_decision ? ''code'' then return ops_decision;end if;return jsonb_build_object(''kind'',''blocked'');end if;\ninsert into turn_private.text_dispatches(lease_token,turn_id,consent_id,policy_id)\n    values(p_lease_token,p_turn_id,c.consent_id,c.policy_id) on conflict do nothing;\n  if not found then return jsonb_build_object(''kind'',''blocked''); end if;\n  insert into turn_private.planning_model_dispatches(lease_token,turn_id,owner_id,task_id,scope_id,attempt_id)\n    values(p_lease_token,p_turn_id,w.owner_id,j.task_id,p_scope_id,p_attempt_id) on conflict do nothing;\n  if not found then raise exception ''DISPATCH_CONFLICT''; end if;\n  return jsonb_build_object(''kind'',''authorized'');\nend ","result":"jsonb","strict":false,"identity":"p_turn_id uuid, p_lease_token uuid, p_context_digest text, p_scope_id uuid, p_attempt_id uuid","language":"plpgsql","parallel":"u","arguments":"p_turn_id uuid, p_lease_token uuid, p_context_digest text, p_scope_id uuid, p_attempt_id uuid","signature":"public.authorize_planning_dispatch_v1(uuid,uuid,text,uuid,uuid)","definition":"CREATE OR REPLACE FUNCTION public.authorize_planning_dispatch_v1(p_turn_id uuid, p_lease_token uuid, p_context_digest text, p_scope_id uuid, p_attempt_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare ops_decision jsonb; payload jsonb; w turn_private.work%rowtype; c turn_private.text_content%rowtype; j turn_private.planning_comparisons%rowtype;\nbegin\n  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in(''planning_intake_comparison_v2'',''scoped_trip_edit_v1'',''travel_directions_v1'')) then return jsonb_build_object(''