xt)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare ops_decision jsonb; c turn_private.text_content%rowtype;\nbegin\n  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in(''planning_intake_comparison_v2'',''scoped_trip_edit_v1'',''travel_directions_v1'')) then return jsonb_build_object(''kind'',''blocked''); end if;\n  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode=''planning_comparison_v1'')\n    then return jsonb_build_object(''kind'',''blocked''); end if;\n  if not turn_private.lock_text_work(p_turn_id,p_lease_token) then return jsonb_build_object(''kind'',''blocked''); end if;\n  select * into c from turn_private.text_content where turn_id=p_turn_id;\n  if c.policy_id is distinct from p_policy_id or not exists(select 1 from turn_private.text_policies where id=p_policy_id and provider=p_provider and context_mode=''current_input_v1'') then return jsonb_build_object(''kind'',''blocked''); end if;\n  ops_decision:=ops_control_private.work_decision_v1(p_turn_id,p_lease_token,''model'');if ops_decision->>''kind'' is distinct from ''allowed'' then if ops_decision ? ''code'' then return ops_decision;end if;return jsonb_build_object(''kind'',''blocked'');end if;\ninsert into turn_private.text_dispatches(lease_token,turn_id,consent_id,policy_id) values(p_lease_token,p_turn_id,c.consent_id,c.policy_id) on conflict do nothing;\n  if not found then return jsonb_build_object(''kind'',''blocked''); end if;\n  return jsonb_build_object(''kind'',''authorized'');\nend $function$\n","volatility":"v","securityDefiner":true},"public.authorize_text_task_dispatch(uuid,uuid,uuid,text,text)":{"acl":"{postgres=X/postgres,service_role=X/postgres}","md5":"f978993d3297511977bcd68d0f4bc4d3","kind":"f","owner":"postgres","config":["search_path=\"\""],"prosrc":"\ndeclare ops_decision jsonb; payload jsonb; c turn_private.text_content%rowtype;\nbegin\n  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in(''planning_intake_comparison_v2'',''scoped_trip_edit_v1'',''travel_directions_v1'')) then return jsonb_build_object(''kind'',''blocked''); end if;\n  payload:=public.read_text_work(p_turn_id,p_lease_token);\n  if payload->>''kind'' is distinct from ''task_input'' or payload->>''policyId'' is distinct from p_policy_id::text\n    or payload->>''provider'' is distinct from p_provider or payload->>''contextDigest'' is distinct from p_context_digest then return jsonb_build_object(''kind'',''blocked''); end if;\n  select * into c from turn_private.text_content where turn_id=p_turn_id;\n  ops_decision:=ops_control_private.work_decision_v1(p_turn_id,p_lease_token,''model'');if ops_decision->>''kind'' is distinct from ''allowed'' then if ops_decision ? ''code'' then return ops_decision;end if;return jsonb_build_object(''kind'',''blocked'');end if;\ninsert into turn_private.text_dispatches(lease_token,turn_id,consent_id,policy_id) values(p_lease_token,p_turn_id,c.consent_id,c.policy_id) on conflict do nothing;\n  if not found then return jsonb_build_object(''kind'',''blocked''); end if;\n  return jsonb_build_object(''kind'',''authorized'');\nend ","result":"jsonb","strict":false,"identity":"p_turn_id uuid, p_lease_token uuid, p_policy_id uuid, p_provider text, p_context_digest text","language":"plpgsql","parallel":"u","arguments":"p_turn_id uuid, p_lease_token uuid, p_policy_id uuid, p_provider text, p_context_digest text","signature":"public.authorize_text_task_dispatch(uuid,uuid,uuid,text,text)","definition":"CREATE OR REPLACE FUNCTION public.authorize_text_task_dispatch(p_turn_id uuid, p_lease_token uuid, p_policy_id uuid, p_provider text, p_context_digest text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare ops_decision jsonb; payload jsonb; c turn_private.text_content%rowtype;\nbegin\n  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in(''planning_intake_comparison_v2'',''scoped_trip_edit_v1'',''travel_directions_v1'')) then return jsonb_build_object(''kind'',''blocked''); end if;\n  payload:=public.read_text_work(p_turn_id,p_lease_token);\n  if payload->>''kind'' is distinct from ''task_input'' or payload->>''policyId'' is distinct from p_policy_id::text\n    or payload->>''provider'' is distinct from p_provider or payload->>''contextDigest'' is distinct from p_context_digest then return jsonb_build_object(''kind'',''blocked''); end if;\n  select * into c from turn_private.text_content where turn_id=p_turn_id;\n  ops_decision:=ops_control_private.work_decision_v1(p_turn_id,p_lease_token,''model'');if ops_decision->>''kind'' is distinct from ''allowed'' then if ops_decision ? ''code'' then return ops_decision;end if;return jsonb_build_object(''kind'',''blocked'');end if;\ninsert into turn_private.text_dispatches(lease_token,turn_id,consent_id,policy_id) values(p_lease_token,p_turn_id,c.consent_id,c.policy_id) on conflict do nothing;\n  if not found then return jsonb_build_object(''kind'',''blocked''); end if;\n  return jsonb_build_object(''kind'',''authorized'');\nend $function$\n","volatility":"v","securityDefiner":true},"public.dispatch_model_budget(uuid,uuid,uuid)":{"acl":"{postgres=X/postgres,service_role=X/postgres}","md5":"e3717df36f7c8a136d8917da6dae09f9","kind":"f","owner":"postgres","config":["search_path=\"\""],"prosrc":"\ndeclare ops_decision jsonb; s public.model_budget_scopes%rowtype; a public.model_budget_attempts%rowtype; p public.model_budget_provider_limits%rowtype;\n  total_cost numeric; provider_cost numeric; task_cost numeric; active_count bigint; task_count bigint;\nbegin\n  ops_decision:=ops_control_private.ledger_decision_v1(p_scope_id,p_owner_id,p_attempt_id);if ops_decision->>''kind'' is distinct from ''allowed'' then if ops_decision->>''kind''=''unavailable'' then return ops_decision;end if;return ops_decision||jsonb_build_object(''kind'',''disabled'');end if;\nselect * into s from public.model_budget_scopes where id = p_scope_id for update;\n  if not found or s.owner_id is distinct from p_owner_id then return jsonb_build_object(''kind'',''unavailable''); end if;\n  select * into a from public.model_budget_attempts where scope_id = p_scope_id and attempt_id = p_attempt_id;\n  if not found then return jsonb_build_object(''kind'',''unavailable''); end if;\n  if a.status <> ''reserved'' then return jsonb_build_object(''kind'',''duplicate'',''status'',a.status); end if;\n  select * into p from public.model_budget_provider_limits where scope_id = p_scope_id and provider = a.provider for share;\n  if not found or not s.enabled or s.frozen or not p.enabled or p.model <> a.model or p.price_version <> a.price_version then\n    return jsonb_build_object(''kind'',''disabled'');\n  end if;\n  if s.expires_at <= clock_timestamp() then return jsonb_build_object(''kind'',''expired''); end if;\n  select\n    coalesce(sum(case when status = ''settled'' then actual_micros when status = ''released'' then 0 else reserved_micros end),0),\n    coalesce(sum(case when status = ''settled'' then actual_micros when status = ''released'' then 0 else reserved_micros end) filter (where provider = a.provider),0),\n    coalesce(sum(case when status = ''settled'' then actual_micros when status = ''released'' then 0 else reserved_micros end) filter (where task_id = a.task_id),0),\n    count(*) filter (where status in (''reserved'',''dispatched'',''pending'')),\n    count(*) filter (where task_id = a.task_id)\n  into total_cost, provider_cost, task_cost, active_count, task_count\n  from public.model_budget_attempts where scope_id = p_scope_id;\n  if a.reserved_micros > p.attempt_limit_micros or total_cost > s.limit_micros\n    or provider_cost > p.limit_micros or task_cost > s.task_limit_micros\n    or active_count > s.concurrency_limit or task_count > s.task_attempt_limit then\n    return jsonb_build_object(''kind'',''exhausted'');\n  end if;\n  update public.model_budget_attempts set status = ''dispatched'', updated_at = clock_timestamp()\n    where scope_id = p_scope_id and attempt_id = p_attempt_id;\n  return jsonb_build_object(''kind'',''dispatched'');\nend;\n","result":"jsonb","strict":false,"identity":"p_scope_id uuid, p_owner_id uuid, p_attempt_id uuid","language":"plpgsql","parallel":"u","arguments":"p_scope_id uuid, p_owner_id uuid, p_attempt_id uuid","signature":"public.dispatch_model_budget(uuid,uuid,uuid)","definition":"CREATE OR REPLACE FUNCTION public.dispatch_model_budget(p_scope_id uuid, p_owner_id uuid, p_attempt_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare ops_decision jsonb; s public.model_budget_scopes%rowtype; a public.model_budget_attempts%rowtype; p public.model_budget_provider_limits%rowtype;\n  total_cost numeric; provider_cost numeric; task_cost numeric; active_count bigint; task_count bigint;\nbegin\n  ops_decision:=ops_control_private.ledger_decision_v1(p_scope_id,p_owner_id,p_attempt_id);if ops_decision->>''kind'' is distinct from ''allowed'' then if ops_decision->>''kind''=''unavailable'' then return ops_decision;end if;return ops_decision||jsonb_build_object(''kind'',''disabled'');end if;\nselect * into s from public.model_budget_scopes where id = p_scope_id for update;\n  if not found or s.owner_id is distinct from p_owner_id then return jsonb_build_object(''kind'',''unavailable''); end if;\n  select * into a from public.model_budget_attempts where scope_id = p_scope_id and attempt_id = p_attempt_id;\n  if not found then return jsonb_build_object(''kind'',''unavailable''); end if;\n  if a.status <> ''reserved'' then return jsonb_build_object(''kind'',''duplicate'',''status'',a.status); end if;\n  select * into p from public.model_budget_provider_limits where scope_id = p_scope_id and provider = a.provider for share;\n  if not found or not s.enabled or s.frozen or not p.enabled or p.model <> a.model or p.price_version <> a.price_version then\n    return jsonb_build_object(''kind'',''disabled'');\n  end if;\n  if s.expires_at <= clock_timestamp() then return jsonb_build_object(''kind'',''expired''); end if;\n  select\n    coalesce(sum(case when status = ''settled'' then actual_micros when status = ''released'' then 0 else reserved_micros end),0),\n    coalesce(sum(case when status = ''settled'' then actual_micros when status = ''released'' then 0 else reserved_micros end) filter (where provider = a.provider),0),\n    coalesce(sum(case when status = ''settled'' then actual_micros when status = ''released'' then 0 else reserved_micros end) filter (where task_id = a.task_id),0),\n    count(*) filter (where status in (''reserved'',''dispatched'',''pending'')),\n    count(*) filter (where task_id = a.task_id)\n  into total_cost, provider_cost, task_cost, active_count, task_count\n  from public.model_budget_attempts where scope_id = p_scope_id;\n  if a.reserved_micros > p.attempt_limit_micros or total_cost > s.limit_micros\n    or provider_cost > p.limit_micros or task_cost > s.task_limit_micros\n    or active_count > s.concurrency_limit or task_count > s.task_attempt_limit then\n    return jsonb_build_object(''kind'',''exhausted'');\n  end if;\n  update public.model_budget_attempts set status = ''dispatched'', updated_at = clock_timestamp()\n    where scope_id = p_scope_id and attempt_id = p_attempt_id;\n  return jsonb_build_object(''kind'',''dispatched'');\nend;\n$function$\n","volatility":"v","securityDefiner":true},"public.grounded_ai_assist_work_v1(jsonb)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","md5":"d99f9666afd994783d72abadc44fa4e0","kind":"f","owner":"postgres","config":["search_path=\"\""],"prosrc":"\ndeclare\n  u uuid; s uuid; action text; tid uuid;\n  g turn_private.grounded_turns%rowtype;\n  job turn_private.grounded_ai_assist_jobs%rowtype;\n  result jsonb;\nbegin\n  if p_input is null or jsonb_typeof(p_input) <> ''object'' then raise exception ''INVALID_INPUT''; end if;\n  action := p_input->>''action'';\n  if action is null or action not in (''ensure'', ''complete'') then raise exception ''INVALID_INPUT''; end if;\n\n  if action = ''ensure'' then\n    if (select array_agg(key order by key) from jsonb_object_keys(p_input) key) <> array[''action'',''turnId'']\n      or jsonb_typeof(p_input->''turnId'') is distinct from ''string''\n      or (p_input->>''turnId'') !~* ''^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$''\n      then raise exception ''INVALID_INPUT''; end if;\n    tid := (p_input->>''turnId'')::uuid;\n    u := turn_private.text_owner();\n    s := (auth.jwt()->>''session_id'')::uuid;\n    if not turn_private.lock_turn(tid, u, s) then return jsonb_build_object(''kind'', ''unavailable''); end if;\n\n    -- Historical jobs retain identity only while the original source is eligible.\n    result := public.read_grounded_ai_assist_context_v1(tid);\n    if result->>''kind'' is distinct from ''context'' then\n      return jsonb_build_object(''kind'',case when result->>''kind''=''not_applicable'' then ''not_applicable'' else ''unavailable'' end);\n    end if;\n    select * into g from turn_private.grounded_turns where turn_id = tid and owner_id = u;\n    if not found or g.original_outcome is distinct from ''blocked'' then return jsonb_build_object(''kind'', ''not_applicable''); end if;\n\n    select * into job from turn_private.grounded_ai_assist_jobs where turn_id = tid for update;\n    if not found then\n      return ops_control_private.c2_unqualified_decision_v1(tid);\ninsert into turn_private.grounded_ai_assist_jobs(turn_id, owner_id, status, started_at)\n        values (tid, u, ''running'', clock_timestamp())\n        returning * into job;\n      return jsonb_build_object(''kind'', ''claimed'', ''jobId'', job.id, ''claimToken'', job.claim_token);\n    end if;\n    if job.owner_id <> u then return jsonb_build_object(''kind'', ''unavailable''); end if;\n    if job.status in (''succeeded'', ''failed'', ''cancelled'') then\n      return jsonb_build_object(''kind'', ''done'', ''jobId'', job.id, ''status'', job.status, ''outcome'', job.outcome, ''errorCode'', job.error_code);\n    end if;\n    if job.status = ''running'' and job.started_at > clock_timestamp() - interval ''2 minutes'' then\n      return jsonb_build_object(''kind'', ''pending'', ''jobId'', job.id);\n    end if;\n    -- Either still ''queued'' (should not normally happen, since insert above\n    -- starts a job ''running'' directly) or a ''running'' claim old enough to\n    -- treat as an abandoned attempt. A fresh claim_token fences off any late\n    -- completion from whoever held the job before this reclaim.\n    return ops_control_private.c2_unqualified_decision_v1(tid);\nupdate turn_private.grounded_ai_assist_jobs\n      set status = ''running'', started_at = clock_timestamp(), finished_at = null, outcome = null, error_code = null, claim_token = gen_random_uuid()\n      where id = job.id\n      returning * into job;\n    return jsonb_build_object(''kind'', ''claimed'', ''jobId'', job.id, ''claimToken'', job.claim_token);\n  end if;\n\n  -- complete\n  if (select array_agg(key order by key) from jsonb_object_keys(p_input) key) <> array[''action'',''claimToken'',''jobId'',''outcome'']\n    or jsonb_typeof(p_input->''jobId'') is distinct from ''string''\n    or (p_input->>''jobId'') !~* ''^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$''\n    or jsonb_typeof(p_input->''claimToken'') is distinct from ''string''\n    or (p_input->>''claimToken'') !~* ''^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$''\n    or jsonb_typeof(p_input->''outcome'') <> ''object'' or p_input->''outcome''->>''kind'' not in (''succeeded'', ''failed'')\n    then raise exception ''INVALID_INPUT''; end if;\n\n  u := turn_private.text_owner();\n  -- Read identity, acquire the original owner/session/source fence, then lock job.\n  select * into job from turn_private.grounded_ai_assist_jobs where id = (p_input->>''jobId'')::uuid;\n  if not found then raise exception ''OPS_NOT_FOUND''; end if;\n  if job.owner_id <> u then raise exception ''UNAUTHENTICATED''; end if;\n  result := public.read_grounded_ai_assist_context_v1(job.turn_id);\n  if result->>''kind'' is distinct from ''context'' then return jsonb_build_object(''kind'',''unavailable''); end if;\n  select * into job from turn_private.grounded_ai_assist_jobs where id = (p_input->>''jobId'')::uuid for update;\n  if not found or job.owner_id <> u then return jsonb_build_object(''kind'',''unavailable''); end if;\n  if job.status <> ''running'' then raise exception ''OPS_CONFLICT''; end if;\n  if (p_input->>''claimToken'')::uuid is distinct from job.claim_token then raise exception ''OPS_CONFLICT''; end if;\n\n  if p_input->''outcome''->>''kind'' = ''succeeded'' then\n    if jsonb_typeof(p_input->''outcome''->''result'') <> ''object'' then raise exception ''INVALID_INPUT''; end if;\n    update turn_private.grounded_ai_assist_jobs\n      set status = ''succeeded'', finished_at = clock_timestamp(), outcome = p_input->''outcome''->''result''\n      where id = job.id;\n    result := jsonb_build_object(''kind'', ''succeeded'', ''jobId'', job.id);\n  else\n    if length(btrim(p_input->''outcome''->>''errorCode'')) not between 1 and 60 then raise exception ''INVALID_INPUT''; end if;\n    update turn_private.grounded_ai_assist_jobs\n      set status = ''failed'', finished_at = clock_timestamp(), error_code = p_input->''outcome''->>''errorCode''\n      where id = job.id;\n    result := jsonb_build_object(''kind'', ''failed'', ''jobId'', job.id);\n  end if;\n  return result;\nend ","result":"jsonb","strict":false,"identity":"p_input jsonb","language":"plpgsql","parallel":"u","arguments":"p_input jsonb","signature":"public.grounded_ai_assist_work_v1(jsonb)","definition":"CREATE OR REPLACE FUNCTION public.grounded_ai_assist_work_v1(p_input jsonb)\n RETURNS jsonb\n LANGUAGE p