ists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in(''planning_intake_comparison_v2'',''scoped_trip_edit_v1'',''travel_directions_v1'')) then return jsonb_build_object(''kind'',''stale''); end if;\n  if (select auth.role())<>''service_role'' or p_turn_id is null or p_lease_token is null then raise exception ''INVALID_INPUT''; end if;\n  select * into w from turn_private.work where turn_id=p_turn_id;\n  if not found or not turn_private.lock_turn(w.turn_id,w.owner_id,w.session_id) then return jsonb_build_object(''kind'',''stale''); end if;\n  select * into w from turn_private.work where turn_id=p_turn_id for update;\n  if w.state<>''leased'' or w.lease_token is distinct from p_lease_token or w.expires_at<=clock_timestamp()\n    or w.execution_mode<>''planning_comparison_v1'' then return jsonb_build_object(''kind'',''stale''); end if;\n  ops_decision:=ops_control_private.work_decision_v1(p_turn_id,p_lease_token,''model'');\n if not(ops_decision ? ''code'') then ops_decision:=ops_control_private.work_decision_v1(p_turn_id,p_lease_token,''tool'');end if;\n if ops_decision->>''code'' in(''OPS_CONTROL_DISABLED'',''OPS_SCOPE_UNAVAILABLE'') then\n declare ops_attempt record;ops_accounting text:=''not_dispatched'';ops_task uuid;begin\n  ops_task:=(select task_id from turn_private.planning_comparisons where turn_id=p_turn_id and owner_id=w.owner_id);\n  for ops_attempt in select a.scope_id,a.attempt_id,a.status from public.model_budget_attempts a\n   join public.model_budget_scopes s on s.id=a.scope_id where a.task_id=ops_task and s.owner_id=w.owner_id\n   order by a.scope_id,a.attempt_id loop\n   if ops_attempt.status in(''dispatched'',''pending'',''settled'') then ops_accounting:=''pending'';end if;\n   if ops_attempt.status=''dispatched'' then perform public.finish_model_budget(ops_attempt.scope_id,w.owner_id,ops_attempt.attempt_id,''pending'',null);\n   elsif ops_attempt.status=''reserved'' then perform public.finish_model_budget(ops_attempt.scope_id,w.owner_id,ops_attempt.attempt_id,''release'',null);end if;\n  end loop;\n  update turn_private.planning_comparisons set state=''paused_unknown'' where turn_id=p_turn_id and owner_id=w.owner_id;\n  update turn_private.text_content set output_kind=''blocked'',output_text=case when locale=''zh''\n   then ''此能力暂时停用，或当前城市范围无法核实。请打开已有行程或已保存成果，按原确认流程手工调整；不会自动重发已发送请求。''\n   else ''This capability is paused or the current city scope cannot be qualified. Open an existing Trip or saved result and edit manually through its original confirmation flow. Sent requests will not be retried automatically.'' end\n   where turn_id=p_turn_id and owner_id=w.owner_id and hidden_at is null;\n  perform turn_private.terminal(p_turn_id,''unavailable'',(select attempt from turn_private.work where turn_id=p_turn_id));\n  update turn_private.service_task_capacity set state=''released'',released_at=clock_timestamp() where task_id=ops_task and state=''reserved'';\n  return jsonb_build_object(''kind'',''ops_paused'',''code'',ops_decision->>''code'',''accounting'',ops_accounting);\n end;end if;\nupdate turn_private.planning_comparisons set state=''paused_unknown'' where turn_id=p_turn_id and state=''queued'';\n  update turn_private.work set state=''queued'',lease_token=null,expires_at=null where turn_id=p_turn_id;\n  return jsonb_build_object(''kind'',''paused_unknown'');\nend ","result":"jsonb","strict":false,"identity":"p_turn_id uuid, p_lease_token uuid","language":"plpgsql","parallel":"u","arguments":"p_turn_id uuid, p_lease_token uuid","signature":"public.pause_planning_comparison_v1(uuid,uuid)","definition":"CREATE OR REPLACE FUNCTION public.pause_planning_comparison_v1(p_turn_id uuid, p_lease_token uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare ops_decision jsonb; w turn_private.work%rowtype;\nbegin\n  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in(''planning_intake_comparison_v2''